                state["unlock_streak"] = state.get("unlock_streak", 0) + 1
                if state["unlock_streak"] >= 5:
                    state["phase"] = "ESCAPE"
                    state["unlock_streak"] = 0
            else:
                state["unlock_streak"] = 0
        else:
            # Not in activation zone, go back to approach phase
            state["phase"] = "APPROACH"
            state["unlock_streak"] = 0
        fx, fy = fx_cmd, fy_cmd
        state["impulse"] = impulse
    elif state["phase"] == "ESCAPE":
        # Apply forward force to move towards exit
        front, up, down = sandbox.get_whisker_readings()
        # Adjust force based on whisker readings
        if front < 2.0:  # If close to a wall
            fx = 15.0
        else:
            fx = 30.0
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Maintain position in exit zone
        fx, fy = 0.0, w_comp  # No force applied
    sandbox.apply_agent_force(fx, fy)

import math

ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0
STRUCTURAL_IMPULSE_LIMIT = 125.0

def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": -34.0,
        "bspd": 100.0,
    }

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "impulse": 0.0,
            "unlock_streak": 0,
            "exit_hold": 0
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    vx_p, vy_p = sandbox.get_agent_velocity()

    # Update state
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    # Approach phase: navigate to activation zone
    if state["phase"] == "APPROACH":
        # Check if in activation zone
        if cfg["act_lo"] <= x <= cfg["act_hi"]:
            # Check physical velocity
            if abs(vx_p) < 0.5:
                state["phase"] = "UNLOCK"
                state["t"] = 0
        else:
            # Apply forward force to move towards activation zone
            target_x = 7.5  # Center of activation zone
            fx = 20.0 * (target_x - x) - 5.0 * vx_p
            fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
    elif state["phase"] == "UNLOCK":
        # Apply backward force to trigger unlock
        fx_cmd = -35.0
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Check velocity
        spd = math.hypot(vx_p, vy_p)
        if spd >= 100.0:
            fx_cmd, fy_cmd = 0.0, 0.0
        # Check structural impulse
        impulse = state["impulse"] + abs(fx_cmd * TIME_STEP)
        if impulse > STRUCTURAL_IMPULSE_LIMIT:
            fx_cmd, fy_cmd = 0.0, 0.0
        # Check unlock conditions
        if fx_cmd < -34.0 and spd < 100.0:
            state["unlock_streak"] = state.get("unlock_streak", 0) + 1
            if state["unlock_streak"] >= 5:
                state["phase"] = "ESCAPE"
                state["unlock_streak"] = 0
        else:
            state["unlock_streak"] = 0
        fx, fy = fx_cmd, fy_cmd
        state["impulse"] = impulse
    elif state["phase"] == "ESCAPE":
        # Use whisker readings to adjust force
        front, up, down = sandbox.get_whisker_readings()
        # Avoid wall collisions
        if front < 2.0:
            fx = 15.0
        else:
            fx = 30.0
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Move toward exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Maintain position in exit zone
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)
